class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        ListNode* first = head;
        for (int i = 1; i < k; i++) {
            first = first->next;
        }
        ListNode* second = head;
        ListNode* scout = first;
        while (scout->next != nullptr) {
            scout = scout->next;
            second = second->next;
        }
        int tmp = first->val;
        first->val = second->val;
        second->val = tmp;
        return head;
    }
};
